// Utility Methods for dealing with FileReference Objects
export interface UploadProgress {
    loaded: number;
    total: number;
    /** NaN when the browser couldn't determine total size (lengthComputable === false) */
    percent: number;
}

export type ProgressCallback = (progress: UploadProgress) => void;
export type CompleteCallback<T> = (result: T) => void;

// Start File reference Upload gets a "FileReference" json object in return that
// can be used in subsequent calls.
export function startFileReferenceUpload(
    fileName: string,
    size: number,
    fileDateTime: Date
): Promise<any> {
    const body = {
        fileName,
        size,
        fileDateTime: fileDateTime.toISOString(),
        outputtype: "Json",
    };
    // Starting Upload does NOt require the XHR / progress tracking methods.
    return post("/REST/FileReferenceService/StartUpload", body)
        .then((response) => {
            return response.StartUploadResult;
        });
}

export function uploadChunk(
    id: string,
    chunk: Uint8Array,
    onProgress?: ProgressCallback,
    onComplete?: CompleteCallback<string>
): Promise<string> {
    const body = {
        id,
        chunk: '"' + bytesToBase64(chunk) + '"',
        outputtype: "Json",
    };

    return postAndGetRawJson("/REST/FileReferenceService/UploadChunk", body, onProgress).then(
        (response) => {
            onComplete?.(response);
            return response;
        }
    );
}

export function finishUpload(
    id: string,
    onProgress?: ProgressCallback,
    onComplete?: CompleteCallback<string>
): Promise<string> {
    const body = {
        id,
        outputtype: "Json",
    };

    return postAndGetRawJson("/REST/FileReferenceService/FinishUpload", body, onProgress).then(
        (response) => {
            onComplete?.(response);
            return response;
        }
    );
}

export async function uploadFileThroughFileReferenceService(
    fileName: string,
    fileContents: Uint8Array,
    onProgress?: ProgressCallback,
    onComplete?: CompleteCallback<string>
): Promise<any> {
    const fileRef = await startFileReferenceUpload(fileName, fileContents.length, new Date());
    await uploadChunk(fileRef.Id, fileContents, onProgress);
    await finishUpload(fileRef.Id);
    onComplete?.(fileRef.Id);
    return fileRef;
}

// Chunked to avoid blowing the call stack from String.fromCharCode(...bytes) on large files.
function bytesToBase64(bytes: Uint8Array): string {
    let binary = "";
    const chunkSize = 0x8000;
    for (let i = 0; i < bytes.length; i += chunkSize) {
        binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
    }
    return btoa(binary);
}
